import json,hashlib
from pathlib import Path
b=Path('/Users/nahyeonbin/Desktop/_Codex/ducttape-poster-round12')
fixed=['planning/final-evidence.json','report.md','raw-score-matrices.json','coordinator/R12-C1/plan.json','checks/root-whole-five-visual-views.json','snapshots/candidate-l/SKILL.md','snapshots/candidate-l/references/parallel-production.md','snapshots/candidate-l/references/visual-research.md','snapshots/candidate-l/references/art-direction.md','snapshots/candidate-l/references/evaluation-loop.md','review_rules.md','summarize.py','planning/prospective-critic-label.json','planning/single-five-production-closure.json']
