 p.append(b/f'reviews/R12-C1/{w}/packet.json')
 for c in ['craft','editorial','portfolio']:
  for f in [f'{c}.observations.json','launch.json','completion.json']:p.append(b/f'reviews/R12-C1/{w}/cli/{c}/{f}')
